import {canonical} from './domain.mjs';
export const instrumentSchema=1;
export const identitySpec=Object.freeze({strings:{number:[1,24],integer:true},scale_mm:{number:[100,1500]},scale_unit:{options:['mm','in']},tuning:{text:300},handedness:{options:['right','left','ambidextrous']}});
const common={position:{text:100},manufacturer:{text:200},model:{text:200},notes:{text:2000},installed_on:{date:true}};
export const componentSpecs=Object.freeze({
 pickup:{...common,type:{options:['single_coil','humbucker','p90','active','other']},coils:{options:['single','dual','stacked','other']},conductors:{options:['1','2','3','4','5','other']},colour_convention:{text:200},measured_dcr_ohm:{number:[0.001,1e8]},measured_inductance_h:{number:[0.000001,1000]}},
 pot:{...common,role:{text:100},series:{text:200},nominal_ohm:{number:[0.001,1e9]},measured_ohm:{number:[0.001,1e9]},taper:{options:['audio','linear','reverse_audio','other']},shaft:{text:200},function:{options:['standard','push_pull','push_push','other']}},
 capacitor:{...common,role:{text:100},series:{text:200},nominal_pf:{number:[0.001,1e12]},measured_pf:{number:[0.001,1e12]},tolerance_percent:{number:[0,100]},voltage_v:{number:[0.001,1e6]},dielectric:{text:200}},
 resistor:{...common,role:{text:100},nominal_ohm:{number:[0.001,1e12]},measured_ohm:{number:[0.001,1e12]},tolerance_percent:{number:[0,100]},capacitor_id:{uuid:true}},
 treble_bleed:{...common,topology:{options:['capacitor_only','parallel','series','other']},capacitor_id:{uuid:true},resistor_id:{uuid:true}},
 switch:{...common,role:{text:100},type:{options:['toggle','blade','push_pull','push_push','other']},configuration:{text:500}},
 jack:{...common,type:{options:['mono','stereo','other']},configuration:{text:500}},
 other:{...common,role:{text:100},description:{text:500}}
});
export const circuitTypes=Object.freeze({pickup:['humbucker','singleCoil','singlecoil','pickup'],pot:['pot'],capacitor:['capacitor'],resistor:['resistor'],treble_bleed:[],switch:['toggle','blade','dpdt','switch'],jack:['jack']});
export const buildSpec=Object.freeze({description:{text:2000},date:{date:true},builder:{text:200},installation_notes:{text:4000},measurements:{text:4000},testing_notes:{text:4000},problems:{text:4000},completed:{text:4000},planned:{text:4000}});
export const uuidPattern=/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i;
const object=v=>v&&typeof v==='object'&&!Array.isArray(v);
function bounded(input,spec){if(!object(input)||Object.keys(input).some(k=>!Object.hasOwn(spec,k)))throw Error('Unsupported instrument fields.');const out={};for(const [k,s] of Object.entries(spec)){const v=input[k];if(v==null||v===''){out[k]=null;continue;}if(s.number){if(typeof v!=='number'||!Number.isFinite(v)||v<s.number[0]||v>s.number[1]||s.integer&&!Number.isInteger(v))throw Error('Invalid '+k+' value.');out[k]=v;}else{if(typeof v!=='string'||s.text&&v.length>s.text||s.options&&!s.options.includes(v)||s.uuid&&!uuidPattern.test(v)||s.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||new Date(v+'T00:00:00Z').toISOString().slice(0,10)!==v))throw Error('Invalid '+k+' value.');out[k]=s.uuid?v.trim().toLowerCase():v.trim();}}return out;}
export function emptyInstrumentWorkspace(){return {schema:1,identity:bounded({},identitySpec),components:[],build:[]};}
export function normaliseInstrumentWorkspace(input,{technical}={}){
 if(!object(input)||input.schema!==1||Object.keys(input).some(k=>!['schema','identity','components','build'].includes(k))||!Array.isArray(input.components)||input.components.length>100||!Array.isArray(input.build)||input.build.length>50||JSON.stringify(input).length>100000)throw Error('Unsupported or oversized instrument documentation.');
 const identity=bounded(input.identity,identitySpec),ids=new Set(),mapped=new Set();
 const components=input.components.map(c=>{if(!object(c)||Object.keys(c).some(k=>!['id','kind','status','circuit_id','fields'].includes(k))||!uuidPattern.test(c.id)||!Object.hasOwn(componentSpecs,c.kind)||!['installed','planned','removed','unknown'].includes(c.status)||ids.has(c.id.toLowerCase()))throw Error('Invalid or duplicate physical component identity.');ids.add(c.id.toLowerCase());const fields=bounded(c.fields,componentSpecs[c.kind]),circuit_id=c.circuit_id||null;if(circuit_id!==null){if(typeof circuit_id!=='string'||circuit_id.length>80||mapped.has(circuit_id)||technical&&!technical.components.some(x=>x.id===circuit_id))throw Error('Invalid, duplicate or stale circuit mapping. Reconcile the documented component before saving.');if(technical&&c.kind!=='other'&&!circuitTypes[c.kind].includes(technical.components.find(x=>x.id===circuit_id).type))throw Error('The physical component kind does not match that circuit representation. Document network members separately.');mapped.add(circuit_id);}return {id:c.id.toLowerCase(),kind:c.kind,status:c.status,circuit_id,fields};});
 for(const c of components)for(const [key,kind] of [['capacitor_id','capacitor'],['resistor_id','resistor']])if(c.fields[key]&&!components.some(x=>x.id===c.fields[key]&&x.kind===kind))throw Error('Associated '+kind+' instance is unavailable.');
 for(const c of components.filter(c=>c.kind==='treble_bleed')){if(c.fields.topology==='capacitor_only'&&c.fields.resistor_id)throw Error('A capacitor-only network cannot include a resistor association.');if(c.fields.topology==='other'&&!c.fields.notes)throw Error('Describe the other topology explicitly.');}
 const build=input.build.map(b=>{if(!object(b)||Object.keys(b).some(k=>!['id','fields'].includes(k))||!uuidPattern.test(b.id)||ids.has(b.id.toLowerCase()))throw Error('Invalid build record identity.');ids.add(b.id.toLowerCase());return {id:b.id.toLowerCase(),fields:bounded(b.fields,buildSpec)};});
 return {schema:1,identity,components,build};
}
export function mappingReport(workspace,technical){const available=new Set(technical.components.map(c=>c.id));return {missing:workspace.components.filter(c=>c.circuit_id&&!available.has(c.circuit_id)),inventoryOnly:workspace.components.filter(c=>!c.circuit_id),circuitOnly:technical.components.filter(c=>!workspace.components.some(x=>x.circuit_id===c.id)),removed:workspace.components.filter(c=>c.status==='removed'&&c.circuit_id)};}
export function compareInstrumentWorkspaces(a,b){if(a?.schema!==1||b?.schema!==1)return {supported:false,changes:[],reason:'Documentation was not captured for both revisions. No historical configuration is inferred.'};a=normaliseInstrumentWorkspace(a);b=normaliseInstrumentWorkspace(b);const changes=[];const walk=(x,y,path)=>{if(canonical(x)===canonical(y))return;if(object(x)&&object(y)){for(const k of [...new Set([...Object.keys(x),...Object.keys(y)])].sort())walk(x[k],y[k],path+'.'+k);}else changes.push({path,before:x??null,after:y??null});};walk(a.identity,b.identity,'instrument');for(const key of ['components','build']){const left=new Map(a[key].map(c=>[c.id,c])),right=new Map(b[key].map(c=>[c.id,c]));for(const id of [...new Set([...left.keys(),...right.keys()])].sort())walk(left.get(id),right.get(id),key+'.'+id);}for(const change of changes){const [group,id,...field]=change.path.split('.');if(group==='components'){const c=b.components.find(c=>c.id===id)||a.components.find(c=>c.id===id),kind={pickup:'Pickup',pot:'Potentiometer',capacitor:'Capacitor',resistor:'Resistor',treble_bleed:'Treble bleed',switch:'Switch',jack:'Output jack',other:'Other component'}[c?.kind]||'Component';change.label=kind+' '+(c?.fields.position||c?.fields.model||id)+' · '+(field.length?field.filter(k=>k!=='fields').join(' ').replaceAll('_',' '):change.before==null?'record added':'record removed');}else change.label=change.path.replaceAll('_',' ');}return {supported:true,changes,reason:'Recorded before/after values by stable instance ID. Added/removed records are not described as replacements without evidence.'};}
export function scaleToMM(value,unit){if(value===''||value==null)return null;const n=Number(value);if(!Number.isFinite(n)||!['mm','in'].includes(unit))throw Error('Invalid scale length or unit.');return n*(unit==='in'?25.4:1);}
export function displayScale(mm,unit='mm'){return mm==null?'':String(mm/(unit==='in'?25.4:1));}
